12	@Injectable({ providedIn: 'root' })
13	export class CountryService {
14	  private readonly http = inject(HttpClient);
15	  private cached$: Observable<Country[]> | null = null;
16	
17	  /** Shared request: guard and page reuse the same result. Failures are not cached. */
18	  load(): Observable<Country[]> {
19	    if (!this.cached$) {
20	      const params = new HttpParams()
21	        .set('fields[0]', 'name')
22	        .set('fields[1]', 'code')
23	        .set('populate[icon][fields][0]', 'url')
24	        .set('populate[icon][fields][1]', 'alternativeText')
25	        .set('sort', 'order:asc');
26	      const request$ = this.http.get<CountriesResponseDto>('/api/countries', { params }).pipe(
27	        map((response) => mapCountries(response.data)),
28	        shareReplay({ bufferSize: 1, refCount: false }),
29	      );
30	      this.cached$ = request$;
31	      // Drop the cache on failure so a retry issues a new request.
32	      request$.subscribe({
33	        error: () => {
34	          if (this.cached$ === request$) this.cached$ = null;
35	        },
36	      });
37	    }
38	    return this.cached$;
39	  }
