11	function button(label: string): HTMLButtonElement {
12	  const found = Array.from(document.querySelectorAll('button')).find(
13	    (b) => b.textContent?.trim() === label,
14	  );
15	  if (!found) throw new Error(`button ${label} not found`);
16	  return found;
17	}
18	
19	describe('US-00 · FR-007 / FR-012 confirm dialog', () => {
20	  let service: ConfirmDialogService;
21	
22	  beforeEach(() => {
23	    // jsdom does not implement showModal/close.
24	    HTMLDialogElement.prototype.showModal = function (this: HTMLDialogElement) {
25	      this.setAttribute('open', '');
26	    };
27	    HTMLDialogElement.prototype.close = function (this: HTMLDialogElement) {
28	      this.removeAttribute('open');
29	    };
30	    service = TestBed.inject(ConfirmDialogService);
31	  });
32	
33	  afterEach(() => {
34	    document.body.querySelectorAll('app-confirm-dialog').forEach((el) => el.remove());
35	  });
36	
37	  it('resolves true on confirm and removes the dialog', async () => {
38	    const result = service.confirm(options);
39	    button('Sí, cambiar').click();
40	    expect(await result).toBe(true);
41	    expect(document.querySelector('app-confirm-dialog')).toBeNull();
42	  });
43	
44	  it('resolves false on cancel', async () => {
45	    const result = service.confirm(options);
46	    button('Cancelar').click();
47	    expect(await result).toBe(false);
48	  });
49	
50	  it('resolves false on Esc (cancel event)', async () => {
51	    const result = service.confirm(options);
52	    const dialog = document.querySelector('dialog');
53	    dialog?.dispatchEvent(new Event('cancel', { cancelable: true }));
54	    expect(await result).toBe(false);
55	  });
56	
57	  it('returns focus to the previously focused element', async () => {
58	    const opener = document.createElement('button');
59	    document.body.appendChild(opener);
60	    opener.focus();
61	    const result = service.confirm(options);
62	    button('Cancelar').click();
63	    await result;
64	    expect(document.activeElement).toBe(opener);
65	    opener.remove();
66	  });
67	});
